<!--
/**
 * Lottie Vue3 组件
 * 
 * 基于lottie-web的Vue3动画组件，支持完整的lottie动画功能
 * 支持本地文件和远程URL两种数据源
 * 
 * === 主要功能 ===
 * 1. 支持本地文件和远程URL两种数据源
 * 2. 完整的播放控制：播放、暂停、停止、重置、跳转等
 * 3. 丰富的事件监听：加载、播放、进度、错误等
 * 4. 自定义进度事件，提供用户友好的帧数显示
 * 5. 支持所有lottie-web的配置选项
 * 
 * === 使用示例 ===
 * 使用本地文件路径
 * <lottie-vue 
 *   path="/animation/feidie.json"
 *   :loop="true"
 *   :autoplay="true"
 *   @onComplete="handleComplete"
 *   @onProgressUpdate="handleProgress"
 * />
 * 
 * 使用远程URL
 * <lottie-vue 
 *   path="https://pic2.candychat.link/test/feidie.json"
 *   :loop="true"
 *   :autoplay="true"
 * />
 * 
 * === 数据源类型说明 ===
 * 
 * 1. **本地文件路径（path - 非http开头）**：
 *    - 传入本地文件路径，如 "/animation/file.json"
 *    - 由lottie-web内部使用XMLHttpRequest加载
 * 
 * 2. **远程URL（path - http/https开头）**：
 *    - 传入完整的HTTP/HTTPS URL
 *    - 组件内部使用fetch获取数据后转为animationData方式加载
 *    - 支持跨域请求（需要服务端配置CORS）
 * 
 * === 事件触发差异说明 ===
 * 
 * **本地JSON文件 vs 远程URL的事件差异：**
 * 
 * 1. **本地文件加载（path="/animation/file.json"）**：
 *    - lottie-web内部使用XMLHttpRequest异步加载
 *    - 完整事件序列：onLoadStart → onConfigReady → onDataReady → onLoadedImages → onDOMLoaded → onLoadComplete
 *    - 所有事件都会按顺序触发，因为存在真实的网络加载过程
 * 
 * 2. **远程URL（path="https://..."）**：
 *    - 组件先使用fetch获取数据，然后转为animationData方式加载
 *    - 事件序列：onLoadStart → (fetch过程) → onConfigReady → onDataReady(可能没有) → onLoadComplete
 *    - 支持自定义请求头和错误处理
 *    - 某些事件可能需要手动触发以保持一致性
 * 
 * 3. **解决方案**：
 *    - 组件内部会检测远程URL并手动补充可能缺失的事件
 *    - 确保两种方式都能获得一致的事件体验
 *    - 以onLoadStart作为加载开始的标志，onLoadComplete作为加载完成的标志   
 * 
 * **事件触发顺序（理想情况）**：
 * 1. onLoadStart - 组件开始加载动画
 * 2. onConfigReady - lottie配置就绪
 * 3. onDataReady - 动画数据加载完成（远程可能没有）
 * 4. onLoadedImages - 图片资源加载完成（如果有图片，则会加载onLoadedImages，没有则不触发，远程数据可能没有）
 * 5. onDOMLoaded - DOM元素创建完成
 * 6. onLoadComplete - 组件加载完成（统一标志）
 * 7. onEnterFrame - 播放过程中每帧触发
 * 8. onProgressUpdate - 播放进度更新（自定义事件）
 * 9. onComplete/onLoopComplete - 播放完成
 */
-->

<template>
    <div ref="lottieContainer" class="lottie-container" :style="containerStyle"></div>
</template>

<script setup>
import { ref, onBeforeUnmount, watch, nextTick, computed } from 'vue';
import { pxToRem } from '@/utils/px-to-rem';

// Props 定义
const props = defineProps({
    // 动画路径 - 支持本地路径和远程URL
    path: {
        type: String,
        required: true,
        // 支持本地路径（如 "/animation/file.json"）和远程URL（如 "https://example.com/animation.json"）
    },
    
    // 基础控制属性
    loop: {
        type: [Boolean, Number],
        default: true
    },
    autoplay: {
        type: Boolean,
        default: true
    },
    name: {
        type: String,
        default: ''
    },
    renderer: {
        type: String,
        default: 'svg',
        validator: (value) => ['svg', 'canvas', 'html'].includes(value)
    },
    
    // 播放控制
    speed: {
        type: Number,
        default: 1
    },
    direction: {
        type: Number,
        default: 1
    },
    startFrame: {
        type: Number,
        default: 0
    },
    useSubFrames: {
        type: Boolean,
        default: true
    },
    
    // 渲染设置
    rendererSettings: {
        type: Object,
        default: () => ({})
    },
    
    // 尺寸控制
    width: {
        type: [String, Number],
        default: '100%'
    },
    height: {
        type: [String, Number],
        default: '100%'
    }
});

// Emits 定义 - 所有可触发的事件
const emit = defineEmits([
    // === lottie-web 原生事件 ===
    'onComplete',        // 动画播放完成事件（非循环模式）- 当动画播放到最后一帧时触发
    'onLoopComplete',    // 循环播放完成事件 - 当动画完成一次循环时触发（循环模式下每次循环结束都会触发）
    'onEnterFrame',      // 进入帧事件 - 动画播放过程中每一帧都会触发，用于实时获取播放进度，频率很高（通常60fps）
    'onConfigReady',     // 配置就绪事件 - 动画配置加载完成时触发，此时可以获取动画的基本信息但还不能播放
    'onDataReady',       // 数据就绪事件 - 动画数据完全加载完成时触发，此时动画可以正常播放
    'onDataFailed',      // 数据加载失败事件 - 当动画数据加载失败时触发，用于错误处理
    'onLoadedImages',    // 图片加载完成事件 - 当动画中的所有图片资源加载完成时触发
    'onDOMLoaded',       // DOM加载完成事件 - 当动画的DOM元素创建完成时触发，可以进行DOM操作
    'onDestroy',         // 销毁事件 - 当动画实例被销毁时触发，用于清理资源
    'onDrawnFrame',      // 帧绘制完成事件 - 每当一帧绘制完成时触发，主要用于性能监控和调试
    
    // === 自定义事件 ===
    'onProgressUpdate',  // 进度更新事件 - 自定义进度事件，提供用户友好的进度信息（1-based帧数和百分比进度）
    'onLoadStart',       // 加载开始事件 - 动画开始加载时触发，用于显示加载状态
    'onLoadComplete'     // 加载完成事件 - 动画加载完成时触发，传递动画实例给父组件
]);

// 响应式数据
const lottieContainer = ref();
const animationInstance = ref(null);
const isReady = ref(false);
const currentFrame = ref(0);
const totalFrames = ref(0);
const lottie = ref(null);

// 事件跟踪，避免重复触发
const triggeredEvents = ref(new Set());

// 计算容器样式
const containerStyle = computed(() => {
    const width = typeof props.width === 'number' ? pxToRem(`${props.width}px`) : pxToRem(props.width);
    const height = typeof props.height === 'number' ? pxToRem(`${props.height}px`) : pxToRem(props.height);
    
    return {
        width,
        height
    };
});

/**
 * 动态加载lottie-web库
 */
const loadLottie = async () => {
    try {
        const lottieModule = await import('lottie-web');
        return lottieModule.default || lottieModule;
    } catch (error) {
        console.error('Failed to load lottie-web:', error);
        return null;
    }
};

/**
 * 获取远程动画数据
 * @param {string} url - 远程URL地址
 * @returns {Promise} 返回Promise对象，包含动画数据
 */
const fetchRemoteAnimationData = async (url) => {
    try {
        console.log('Fetching remote animation data from:', url);
        
        const response = await fetch(url, {
            method: 'GET',
            headers: {
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            }
        });
        
        if (!response.ok) {
            throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        
        const data = await response.json();
        console.log('Remote animation data fetched successfully');
        
        // 验证数据有效性
        if (!validateLottieData(data)) {
            console.warn('Remote data validation failed, but returning data anyway');
        }
        
        return data;
        
    } catch (error) {
        console.error('Failed to fetch remote animation data:', error);
        throw error;
    }
};

/**
 * 验证获取到的数据是否为有效的Lottie动画数据
 * @param {object} data - 要验证的数据
 * @returns {boolean} 是否为有效的Lottie数据
 */
const validateLottieData = (data) => {
    if (!data || typeof data !== 'object') {
        console.warn('Invalid data type for Lottie validation');
        return false;
    }
    
    // 检查基本的Lottie属性
    const requiredProps = ['v', 'fr', 'ip', 'op', 'w', 'h'];
    const hasRequiredProps = requiredProps.every(prop => prop in data);
    
    if (!hasRequiredProps) {
        console.warn('Invalid Lottie data: missing required properties', {
            required: requiredProps,
            present: Object.keys(data).filter(key => requiredProps.includes(key))
        });
        return false;
    }
    
    console.log('Lottie data validation successful');
    return true;
};

/**
 * 判断路径是否为远程URL
 * @param {string} path - 路径字符串
 * @returns {boolean} 是否为远程URL
 */
const isRemoteUrl = (path) => {
    return path && (path.startsWith('http://') || path.startsWith('https://'));
};

/**
 * 初始化lottie动画
 */
const initAnimation = async (type) => {
    console.log('initAnimation', type);
    if (!lottieContainer.value) {
        console.error('Lottie container not found');
        return;
    }

    if (!props.path) {
        console.error('Path is required');
        return;
    }

    // 如果lottie库未加载，先加载
    if (!lottie.value) {
        lottie.value = await loadLottie();
        if (!lottie.value) {
            console.error('Failed to load lottie-web library');
            return;
        }
    }

    // 如果已存在动画实例，先销毁
    if (animationInstance.value) {
        destroyAnimation();
    }

    try {
        // 触发加载开始事件 - 动画开始加载时触发，用于显示加载状态
        emit('onLoadStart');

        let loadParams = {
            container: lottieContainer.value,
            renderer: props.renderer,
            loop: props.loop,
            autoplay: props.autoplay,
            name: props.name
        };

        // 处理不同的数据源
        if (isRemoteUrl(props.path)) {
            // 远程URL：先获取数据，再使用animationData方式加载
            console.log('Fetching remote animation data from:', props.path);
            try {
                const animationData = await fetchRemoteAnimationData(props.path);
                loadParams.animationData = animationData;
                
                // 验证动画数据
                console.log('Validating remote animation data:', {
                    hasFrames: !!(animationData.op && animationData.ip !== undefined),
                    inPoint: animationData.ip,
                    outPoint: animationData.op,
                    frameRate: animationData.fr,
                    version: animationData.v,
                    hasLayers: !!(animationData.layers && animationData.layers.length > 0)
                });
                
                // 检查关键属性
                if (!animationData.op || animationData.op <= 0) {
                    console.warn('Animation data may be invalid: missing or invalid outPoint (op)');
                }
                if (animationData.ip === undefined) {
                    console.warn('Animation data may be invalid: missing inPoint (ip)');
                }
            } catch (error) {
                console.error('Failed to fetch remote animation data:', error);
                emit('onDataFailed', { error: error.message, url: props.path });
                return;
            }
        } else {
            // 本地路径：使用lottie-web的path方式加载
            console.log('Using local path from props:', props.path);
            loadParams.path = props.path;
        }
        
        // 设置渲染配置
        if (props.rendererSettings && Object.keys(props.rendererSettings).length > 0) {
            loadParams.rendererSettings = props.rendererSettings;
        }
        
        // 加载动画
        animationInstance.value = lottie.value?.loadAnimation(loadParams);

        // 绑定事件监听
        bindEvents();

        // 等待动画数据加载完成
        animationInstance.value.addEventListener('data_ready', () => {
            isReady.value = true;
            totalFrames.value = animationInstance.value.totalFrames;
            
            // 确保loop设置正确
            if (props.loop !== animationInstance.value.loop) {
                console.log('Correcting loop setting from', animationInstance.value.loop, 'to', props.loop);
                // 注意：lottie-web在创建后无法直接修改loop，需要重新创建
                // 这里我们记录差异，但不强制修改
            }
            
            setupAnimation();
            
            nextTick(() => {
                // 触发加载完成事件 - 动画加载完成时触发，传递动画实例给父组件
                if (!triggeredEvents.value.has('load_complete')) {
                    emit('onLoadComplete', animationInstance.value);
                    triggeredEvents.value.add('load_complete');
                }
            });
        });

        // 对于远程URL获取的数据，某些事件可能不会自动触发，我们需要手动处理
        if (isRemoteUrl(props.path)) {
            // 使用nextTick确保在DOM更新后执行
            nextTick(() => {
                // 检查是否已经ready，如果是则立即设置
                if (animationInstance.value && animationInstance.value.totalFrames > 0) {
                    console.log('Remote animation data loaded immediately, setting up...');
                    isReady.value = true;
                    totalFrames.value = animationInstance.value.totalFrames;
                    setupAnimation();
                    
                    // 手动触发可能缺失的事件
                    setTimeout(() => {
                        // 对于远程数据方式，手动触发config_ready事件（如果lottie-web没有触发）
                        if (!triggeredEvents.value.has('config_ready')) {
                            console.log('Manually triggering config_ready event for remote data');
                            emit('onConfigReady', { type: 'config_ready', source: 'manual_trigger' });
                            triggeredEvents.value.add('config_ready');
                        }
                        
                        if (!triggeredEvents.value.has('load_complete')) {
                            emit('onLoadComplete', animationInstance.value);
                            triggeredEvents.value.add('load_complete');
                        }
                    }, 10);
                }
            });
        }

    } catch (error) {
        console.error('Failed to load lottie animation:', error);
        // 触发数据加载失败事件 - 动画初始化失败时触发，用于错误处理
        emit('onDataFailed', { error: error.message });
    }
};

/**
 * 本地JSON文件 vs URL获取JSON文件的事件差异说明
 * 
 * === 事件触发顺序（正常情况下）===
 * 1. onLoadStart - 组件开始加载动画
 * 2. onConfigReady - lottie配置就绪
 * 3. onDataReady - 动画数据加载完成
 * 4. onLoadedImages - 图片资源加载完成（如果有）
 * 5. onDOMLoaded - DOM元素创建完成
 * 6. onLoadComplete - 组件加载完成
 * 7. onEnterFrame - 播放过程中每帧触发
 * 8. onProgressUpdate - 播放进度更新（自定义事件）
 * 9. onComplete/onLoopComplete - 播放完成
 */

/**
 * 绑定lottie事件监听
 */
const bindEvents = () => {
    if (!animationInstance.value) return;

    const animation = animationInstance.value;

    // 动画播放完成事件 - 当动画播放到最后一帧时触发（非循环模式）
    animation.addEventListener('complete', (event) => {
        console.log('Animation complete event triggered:', event);
        console.log('Current loop setting:', props.loop);
        
        // 触发完成事件 - 用于监听动画播放结束，适用于非循环动画
        emit('onComplete', event);
    });

    // 循环播放完成事件 - 当动画完成一次循环时触发（循环模式下每次循环结束都会触发）
    animation.addEventListener('loopComplete', (event) => {
        // 触发循环完成事件 - 用于监听每次循环结束，适用于循环动画
        emit('onLoopComplete', event);
    });

    // 进入帧事件 - 动画播放过程中每一帧都会触发，用于实时获取播放进度
    animation.addEventListener('enterFrame', (event) => {
        currentFrame.value = event.currentTime;
        totalFrames.value = animation.totalFrames;
        updateProgress();
        // 触发帧进入事件 - 每帧都触发，用于实时监控播放进度，频率很高（通常60fps）
        // 修正currentTime显示为1-based（用户友好的帧数显示）
        emit('onEnterFrame', {
            currentTime: event.currentTime + 1<= event.totalTime? event.currentTime + 1: event.totalTime,
            direction: event.direction,
            totalTime: event.totalTime,
            type: "enterFrame"
        });
    });

    // 配置就绪事件 - 动画配置加载完成时触发，此时可以获取动画的基本信息
    animation.addEventListener('config_ready', (event) => {
        console.log('config_ready event triggered by lottie-web');
        triggeredEvents.value.add('config_ready');
        // 触发配置就绪事件 - 动画配置加载完成，可以获取基本信息但还不能播放
        emit('onConfigReady', event);
    });

    // 数据就绪事件 - 动画数据完全加载完成时触发，此时动画可以正常播放
    animation.addEventListener('data_ready', (event) => {
        totalFrames.value = animation.totalFrames;
        // 触发数据就绪事件 - 动画数据完全加载完成，此时可以开始播放动画
        emit('onDataReady', event);
    });

    // 数据加载失败事件 - 当动画数据加载失败时触发
    animation.addEventListener('data_failed', (event) => {
        // 触发数据加载失败事件 - 动画数据加载失败，用于错误处理
        emit('onDataFailed', event);
    });

    // 图片加载完成事件 - 当动画中的所有图片资源加载完成时触发
    animation.addEventListener('loaded_images', (event) => {
        // 触发图片加载完成事件 - 动画中的所有图片资源加载完成
        emit('onLoadedImages', event);
    });

    // DOM加载完成事件 - 当动画的DOM元素创建完成时触发
    animation.addEventListener('DOMLoaded', (event) => {
        // 触发DOM加载完成事件 - 动画的DOM元素创建完成，可以进行DOM操作
        emit('onDOMLoaded', event);
    });

    // 销毁事件 - 当动画实例被销毁时触发
    animation.addEventListener('destroy', (event) => {
        // 触发销毁事件 - 动画实例被销毁，用于清理资源
        emit('onDestroy', event);
    });

    // 帧绘制完成事件 - 每当一帧绘制完成时触发，主要用于性能监控
    animation.addEventListener('drawnFrame', (event) => {
        // 触发帧绘制完成事件 - 每帧绘制完成时触发，用于性能监控和调试
        emit('onDrawnFrame', event);
    });
};

/**
 * 设置动画初始状态
 */
const setupAnimation = () => {
    if (!animationInstance.value || !isReady.value) {
        console.log('Animation not ready for setup:', { instance: !!animationInstance.value, ready: isReady.value });
        return;
    }

    const animation = animationInstance.value;

    // 设置播放速度
    animation.setSpeed(props.speed);

    // 设置播放方向
    animation.setDirection(props.direction);

    // 设置子帧
    animation.setSubframe(props.useSubFrames);

    // 确保总帧数已设置
    if (animation.totalFrames) {
        totalFrames.value = animation.totalFrames;
        console.log('Total frames set to:', totalFrames.value);
    }

    // 如果设置了开始帧且不是0，跳转到指定帧
    if (props.startFrame > 0) {
        console.log('Setting start frame to:', props.startFrame);
        animation.goToAndStop(props.startFrame, true);
        
        // 如果设置了自动播放，从指定帧开始播放
        if (props.autoplay) {
            console.log('Starting autoplay from frame:', props.startFrame);
            animation.play();
        }
    } else {
        // 确保动画在开始位置
        animation.goToAndStop(0, true);
        
        // 如果没有设置开始帧，且autoplay为true但动画没有自动开始，手动开始播放
        if (props.autoplay) {
            console.log('Starting autoplay from beginning...');
            animation.play();
        }
    }
};

/**
 * 更新播放进度
 */
const updateProgress = () => {
    if (!animationInstance.value) return;

    // 修正显示逻辑：
    // - lottie内部帧数是0-based（0到79）
    // - 用户期望看到1-based显示（1到80）
    // - 进度计算：当前帧/总帧数，但要确保最后一帧显示为100%
    
    const rawCurrentFrame = currentFrame.value; // lottie原始帧数（0-based）
    const displayCurrentFrame = Math.min(Math.round(rawCurrentFrame) + 1, totalFrames.value); // 显示帧数（1-based）
    
    // 进度计算：确保最后一帧显示100%
    let progress = 0;
    if (totalFrames.value > 0) {
        // 当接近最后一帧时（比如79.x），显示为100%
        if (rawCurrentFrame >= totalFrames.value - 1) {
            progress = 1;
        } else {
            progress = rawCurrentFrame / (totalFrames.value - 1);
        }
    }
    
    // 触发进度更新事件 - 自定义进度事件，提供用户友好的进度信息（1-based帧数和百分比进度）
    emit('onProgressUpdate', {
        currentFrame: displayCurrentFrame,
        totalFrames: totalFrames.value,
        progress: Math.min(Math.max(progress, 0), 1)
    });
};

/**
 * 销毁动画实例
 */
const destroyAnimation = () => {
    if (animationInstance.value) {
        animationInstance.value.destroy();
        animationInstance.value = null;
        isReady.value = false;
        currentFrame.value = 0;
        totalFrames.value = 0;
        // 清理事件跟踪
        triggeredEvents.value.clear();
    }
};

// 暴露给父组件的方法
/**
 * 播放动画
 */
const play = () => {
    if (!animationInstance.value) {
        console.log('Cannot play: animation instance not found');
        return;
    }
    
    const animation = animationInstance.value;
    
    // 直接播放动画，不做任何片段限制
    animation.play();
    console.log('Animation play() called');
};

/**
 * 暂停动画
 */
const pause = () => {
    animationInstance.value?.pause();
};

/**
 * 停止动画
 */
const stop = () => {
    animationInstance.value?.stop();
};

/**
 * 设置播放速度
 * @param {number} speed 播放速度，1为正常速度
 */
const setSpeed = (speed) => {
    animationInstance.value?.setSpeed(speed);
};

/**
 * 设置播放方向
 * @param {number} direction 1为正向，-1为反向
 */
const setDirection = (direction) => {
    animationInstance.value?.setDirection(direction);
};

/**
 * 跳转到指定帧并停止
 * @param {number} frame 目标帧
 * @param {boolean} isFrame 是否按帧计算（默认true）
 */
const goToAndStop = (frame, isFrame = true) => {
    animationInstance.value?.goToAndStop(frame, isFrame);
};

/**
 * 跳转到指定帧并播放
 * @param {number} frame 目标帧
 * @param {boolean} isFrame 是否按帧计算（默认true）
 */
const goToAndPlay = (frame, isFrame = true) => {
    animationInstance.value?.goToAndPlay(frame, isFrame);
};

/**
 * 播放指定片段
 * @param {Array} segments 片段数组
 * @param {boolean} forceFlag 是否强制立即更新
 */
const playSegments = (segments, forceFlag = false) => {
    animationInstance.value?.playSegments(segments, forceFlag);
};

/**
 * 获取动画时长
 * @param {boolean} inFrames 是否返回帧数（默认false，返回秒数）
 */
const getDuration = (inFrames = false) => {
    return animationInstance.value?.getDuration(inFrames) || 0;
};


/**
 * 获取动画实例
 */
const getAnimationInstance = () => {
    return animationInstance.value;
};

/**
 * 重置动画到开始位置
 */
const reset = () => {
    if (!animationInstance.value) {
        console.log('Cannot reset: animation instance not found');
        return;
    }
    
    const animation = animationInstance.value;
    console.log('Reset called - going to frame 0 and stopping');
    
    // 重置到第0帧并停止
    animation.goToAndStop(0, true);
    console.log('Animation reset() called');
};

// 监听props变化
watch(
    () => [props.path],
    (newVal, oldVal) => {
        // 只有在真正的数据源变化时才重新初始化
        const [newPath] = newVal || [];
        const [oldPath] = oldVal || [];
        
        // 只有在数据源真正变化时才重新初始化
        const shouldReinit = newPath !== oldPath;
        
        if (shouldReinit) {
            console.log('Data source changed, reinitializing...');
            nextTick(() => {
                initAnimation('watch');
            });
        } else {
            console.log('No significant change, skipping reinitialization');
        }
    },
    { immediate: true }
);

watch(
    () => props.speed,
    (newSpeed) => {
        if (animationInstance.value && isReady.value) {
            animationInstance.value.setSpeed(newSpeed);
        }
    }
);

watch(
    () => props.direction,
    (newDirection) => {
        if (animationInstance.value && isReady.value) {
            animationInstance.value.setDirection(newDirection);
        }
    }
);

watch(
    () => props.startFrame,
    (newStartFrame) => {
        if (animationInstance.value && isReady.value) {
            animationInstance.value.goToAndStop(newStartFrame, true);
        }
    }
);

watch(
    () => props.loop,
    (newLoop) => {
        console.log('Loop setting changed to:', newLoop);
        if (animationInstance.value && isReady.value) {
            // Lottie需要重新初始化才能改变loop设置
            console.log('Loop setting changed, reinitializing...');
            nextTick(() => {
                initAnimation('loop');
            });
        }
    }
);

watch(
    () => props.autoplay,
    (newAutoplay) => {
        if (animationInstance.value && isReady.value) {
            if (newAutoplay) {
                animationInstance.value.play();
            } else {
                animationInstance.value.pause();
            }
        }
    }
);

onBeforeUnmount(() => {
    destroyAnimation();
});

// 暴露方法给父组件
defineExpose({
    play,
    pause,
    stop,
    reset,
    setSpeed,
    setDirection,
    goToAndStop,
    goToAndPlay,
    playSegments,
    getDuration,
    getAnimationInstance,
    // 状态数据
    isReady,
    currentFrame,
    totalFrames
});
</script>

<style scoped>
.lottie-container {
    display: flex;
    align-items: center;
    justify-content: center;
}
</style>
